from bs4 import BeautifulSoup
from pathlib import Path
import re
root=Path('/Users/d111879/Documents/Project/DEMO/Student/Student_mobile/sapp/research/agent_runs/uttar-pradesh-nirf-strict-5-all-remaining/workspaces/santosh-university/tmp/santosh_programs_1372')
for u in (root/'program_urls.txt').read_text().splitlines():
 slug=u.rsplit('/',1)[-1]; f=root/(slug+'.html')
 if not f.exists(): print('MISSING',u); continue
 s=BeautifulSoup(f.read_text(errors='ignore'),'html.parser')
 for x in s(['script','style','noscript','svg']): x.decompose()
 title=' '.join(s.title.get_text(' ',strip=True).split()) if s.title else ''
 heads=[]
 for tag in s.find_all(['h1','h2','h3','h4']):
  t=' '.join(tag.get_text(' ',strip=True).split())
  if t and t not in heads: heads.append(t)
 text=' '.join(s.get_text(' ',strip=True).split())
 vals=[]
 for pat in ['Duration','Eligibility','Course Duration','Duration of Course','years','qualification']:
  for m in list(re.finditer(r'(?i)'+re.escape(pat),text))[:3]:
   a=max(0,m.start()-100); b=min(len(text),m.end()+250)
   sn=' '.join(text[a:b].split())
   if sn not in vals: vals.append(sn)
 print('\\n|',slug,'|',title,'|',' / '.join(heads[:8]),'|')
 for v in vals[:8]: print('  ',v)
PY"

