/bin/bash -lc "python3 - <<'PY'
import sqlite3
con=sqlite3.connect('file:assets/data/career_path.db?mode=ro',uri=True)
# print nodes with parent/roots for science, plus descendants of relevant roots
rows=con.execute('select id,slug,name,stream_id,parent_id from career_nodes order by id').fetchall()
by={r[0]:r for r in rows}
def path(i):
 arr=[]; seen=set()
 while i is not None and i not in seen:
  seen.add(i); r=by[i]; arr.append(r[2]); i=r[4]
 return list(reversed(arr))
for root in [r for r in rows if r[4] is None]:
 if root[3]==1:
  print('\\nROOT',root[0],root[2],root[1])
  for r in rows:
   if r[3]==1 and (root[0]==r[0] or root[0] in [x for x in []]): pass
# all nodes whose path includes common health-related terms
terms=['Science','Medical','Medicine','Dental','Health','Paramedical','Psychology','Forensic','Optometry','Nutrition','Biology','Chemistry','Research','Management']
for r in rows:
 p=' > '.join(path(r[0]))
 if any(t.lower() in p.lower() for t in terms): print(r[0],r[1],p)
PY"

